private static func buildLevel(entries: [Entry], depth: Int, basePath: URL) -> [FileNode] {
    // Group entries by the component at the current depth
    var groups: [String: [Entry]] = [:]
    for entry in entries {
        guard depth < entry.relativeComponents.count else { continue }
        let key = entry.relativeComponents[depth]
        groups[key, default: []].append(entry)
    }

    var nodes: [FileNode] = []
    for (name, groupEntries) in groups {
        let dirURL = basePath.appendingPathComponent(name, isDirectory: true)

        // Leaf files: entries where this is the last component
        let leaves = groupEntries.filter { $0.relativeComponents.count == depth + 1 }
        // Subtree entries: entries with more components
        let deeper = groupEntries.filter { $0.relativeComponents.count > depth + 1 }

        if !deeper.isEmpty {
            // This is a directory
            let childNodes = buildLevel(entries: deeper, depth: depth + 1, basePath: dirURL)
            let leafNodes = leaves.map { entry in
                FileNode(id: entry.url, name: entry.url.lastPathComponent,
                         url: entry.url, isDirectory: false, children: nil)
            }
            // If the directory has only subdirectory children (no leaf files at this level),
            // just add the child nodes. Otherwise combine.
            let allChildren = (childNodes + leafNodes).sorted {
                $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending
            }
            nodes.append(FileNode(
                id: dirURL, name: name, url: dirURL,
                isDirectory: true, children: allChildren
            ))
        } else {
            // All entries are leaf files
            for entry in leaves {
                nodes.append(FileNode(
                    id: entry.url, name: name,
                    url: entry.url, isDirectory: false, children: nil
                ))
            }
        }
    }

    // Sort: directories first, then files, both alphabetically
    return nodes.sorted { lhs, rhs in
        if lhs.isDirectory != rhs.isDirectory { return lhs.isDirectory }
        return lhs.name.localizedCaseInsensitiveCompare(rhs.name) == .orderedAscending
    }
}

func topLevelIndexingRecord() -> IndexingRecord? {
    let kind: IndexingRecord.Kind
    switch self.kind {
    case .tutorial:
        kind = .tutorial
    case .section:
        kind = .tutorialSection
    case .overview:
        kind = .overview
    case .article:
        kind = .article
    case .symbol:
        kind = .symbol
    }

    guard let title = metadata.title, !title.isEmpty else {
        // Nodes without a title are erroneous entries in the symbol graph.
        // A search result cannot be constructed without a title, meaning that
        // an indexing record for this node is useless. The node is skipped.
        assertionFailure("\(identifier.absoluteString.singleQuoted) has an empty title, and cannot have a usable search result")
        return nil
    }

    let summaryParagraph: RenderBlockContent?
    if let abstract = self.abstract {
        summaryParagraph = RenderBlockContent.paragraph(.init(inlineContent: abstract))
    } else if let intro = self.sections.first as? IntroRenderSection, let firstBlock = intro.content.first, case .paragraph = firstBlock {
        summaryParagraph = firstBlock
    } else {
        summaryParagraph = nil
    }

    let summary = summaryParagraph?.rawIndexableTextContent(references: references) ?? ""

    return IndexingRecord(kind: kind, location: .topLevelPage(identifier), title: title, summary: summary, headings: self.headings, rawIndexableTextContent: self.rawIndexableTextContent, platforms: metadata.platforms)
}

