private static func nodeDepth(nodeID: Int, graph: ChoiceGraph) -> Int {
    var depth = 0
    var current = graph.nodes[nodeID].parent
    while let parentID = current {
        depth += 1
        current = graph.nodes[parentID].parent
    }
    return depth
}

package static func rankedEdges(
    failingSignatures: [BitSet],
    passing: PassingSample,
    limit: Int = FuzzTunables.discriminatingEdgeCandidateLimit
) -> [EdgeDiscrimination] {
    guard failingSignatures.isEmpty == false else {
        return []
    }
    var failCounts: [Int: Int] = [:]
    for signature in failingSignatures {
        signature.forEachIndex { edge in
            failCounts[edge, default: 0] += 1
        }
    }

    let failTotal = Double(failingSignatures.count)
    let passTotal = Double(max(1, passing.sampleSize))
    // Floor the pass fraction at "less than one passing run" so never-passing edges rank highest with a finite power instead of dividing by zero.
    let passFloor = 1.0 / (passTotal + 1.0)

    var statistics: [EdgeDiscrimination] = []
    for (edge, failCount) in failCounts {
        let failFraction = Double(failCount) / failTotal
        let passFraction = Double(passing[edge]) / passTotal
        let power = failFraction / max(passFraction, passFloor)
        guard power > 1.0 else {
            continue
        }
        statistics.append(EdgeDiscrimination(
            edge: edge,
            failureHitFraction: failFraction,
            passingHitFraction: passFraction,
            power: power
        ))
    }
    statistics.sort { lhs, rhs in
        if lhs.power != rhs.power {
            return lhs.power > rhs.power
        }
        return lhs.edge < rhs.edge
    }
    return Array(statistics.prefix(limit))
}

private func rootLayer<Value: __Exhaustable.Conformance>(
    for type: Value.Type,
    recursion: RootRecursionBudget,
    nodes: Int,
    domain: ExhaustableDomain
) -> ReflectiveGenerator<Value> {
    switch recursion {
        case let .pinned(recursion):
            return generator(for: type, recursion: recursion, nodes: nodes, domain: domain)
        case let .drawn(ceiling, scaling):
            guard let minimum = (0 ... ceiling).first(where: { candidate in
                guard let cost = budget.minimumNodes(for: ObjectIdentifier(type), recursion: candidate) else {
                    return false
                }
                return cost <= nodes
            }) else {
                preconditionFailure("A validated root allowance must admit a recursion at or below its ceiling")
            }
            let layers = (minimum ... ceiling).map { generator(for: type, recursion: $0, nodes: nodes, domain: domain) }
            return Gen.chooseDepth(in: UInt64(minimum) ... UInt64(ceiling), scaling: scaling)._bound(
                forward: { selected in layers[Int(selected) - minimum].gen.erase() },
                backward: { (_: Value) in UInt64(ceiling) }
            ).wrapped(isReflective: layers.allSatisfy { $0.isReflective })
    }
}

private func buildLayeredContainer(
    _ recipe: DerivedContainerRecipe,
    children: [PayloadPlan],
    recursionAllowance: PayloadRecursionAllowance,
    nodes: Int,
    domain: ExhaustableDomain,
    maximumGeneratedCount: Int,
    maximumBuiltCount: Int
) -> ReflectiveGenerator<Any> {
    var layers = [recipe.empty.wrapped(isReflective: true)]
    for elementIndex in 0 ..< maximumBuiltCount {
        let elementCount = elementIndex + 1
        let entryRecursionAllowance = PayloadRecursionAllowance(
            source: recursionAllowance.source,
            inherited: recursionAllowance.inherited,
            recursive: recursionAllowance.recursive / elementCount
        )
        let recursionAllowances = Array(repeating: entryRecursionAllowance, count: children.count)
        guard let minima = budget.minimumNodes(
            for: children,
            recursionAllowances: recursionAllowances
        ),
            let nodeAllowances = budget.split((nodes - 1) / elementCount, minima: minima)
        else {
            break
        }
        let key = CountedContainerKey(
            type: ObjectIdentifier(recipe.type),
            count: elementCount,
            recursionAllowance: entryRecursionAllowance,
            nodeAllowances: nodeAllowances,
            domain: domain
        )
        switch countedContainers[key] {
            case let .some(existing):
                layers.append(existing)
                continue
            case .none:
                break
        }
        let generators = children.indices.map { childIndex in
            payloadGenerator(
                for: children[childIndex],
                recursionAllowance: recursionAllowances[childIndex],
                nodes: nodeAllowances[childIndex],
                domain: domain
            )
        }
        let layer = recipe.build(.exactly(elementCount), generators.map { $0.gen }).wrapped(
            isReflective: recipe.isReflective && generators.allSatisfy { $0.isReflective }
        )
        countedContainers[key] = layer
        layers.append(layer)
    }
    let builtMaximum = layers.count - 1
    let sampledMaximum = min(maximumGeneratedCount, builtMaximum)
    return recipe.selectCount(sampledMaximum, layers.map { $0.gen }).wrapped(
        isReflective: layers.allSatisfy { $0.isReflective }
    )
}

private func makeGroupLayers(
  from items: [ShapeItemLayer.Item],
  parentGroup: Group?,
  parentGroupPath: [String],
  context: LayerContext
) throws -> [GroupLayer] {
  var groupItems = items.compactMap { $0.item as? Group }.filter { !$0.hidden }
  var otherItems = items.filter { !($0.item is Group) && !$0.item.hidden }

  // Handle the top-level `shapeLayer.items` array. This is typically just a single `Group`,
  // but in practice can be any combination of items. The implementation expects all path-drawing
  // shape items to be managed by a `GroupLayer`, so if there's a top-level path item we
  // have to create a placeholder group.
  if parentGroup == nil, otherItems.contains(where: { $0.item.drawsCGPath }) {
    groupItems = [Group(items: items.map { $0.item }, name: "")]
    otherItems = []
  }

  // Any child items that wouldn't be included in a valid shape render group
  // need to be applied to child groups (otherwise they'd be silently ignored).
  let inheritedItemsForChildGroups = otherItems
    .shapeRenderGroups(groupHasChildGroupsToInheritUnusedItems: !groupItems.isEmpty)
    .unusedItems

  // Groups are listed from front to back,
  // but `CALayer.sublayers` are listed from back to front.
  let groupsInZAxisOrder = groupItems.reversed()

  return try groupsInZAxisOrder.compactMap { group in
    var pathForChildren = parentGroupPath
    if !group.name.isEmpty {
      pathForChildren.append(group.name)
    }

    let childItems = group.items
      .filter { !$0.hidden }
      .map { ShapeItemLayer.Item(item: $0, groupPath: pathForChildren) }

    // Some shape item properties are affected by scaling (e.g. stroke width).
    // The child group may have a `ShapeTransform` that affects the scale of its items,
    // but shouldn't affect the scale of any inherited items. To prevent this scale
    // from affecting inherited items, we have to apply an inverse scale to them.
    let inheritedItems = try inheritedItemsForChildGroups.map { item in
      ShapeItemLayer.Item(
        item: try item.item.scaledCopyForChildGroup(group, context: context),
        groupPath: item.groupPath
      )
    }

    return try GroupLayer(
      group: group,
      items: childItems + inheritedItems,
      groupPath: pathForChildren,
      context: context
    )
  }
}

private func targetDepthsAndDependents(
  for buildTargets: [BuildTarget]
) -> (depths: [BuildTargetIdentifier: Int], dependents: [BuildTargetIdentifier: Set<BuildTargetIdentifier>]) {
  var nonRoots: Set<BuildTargetIdentifier> = []
  for buildTarget in buildTargets {
    nonRoots.formUnion(buildTarget.dependencies)
  }
  let targetsById = Dictionary(elements: buildTargets, keyedBy: \.id)
  var dependents: [BuildTargetIdentifier: Set<BuildTargetIdentifier>] = [:]
  var depths: [BuildTargetIdentifier: Int] = [:]
  let rootTargets = buildTargets.filter { !nonRoots.contains($0.id) }
  var worksList: [(target: BuildTargetIdentifier, depth: Int)] = rootTargets.map { ($0.id, 0) }
  while let (target, depth) = worksList.popLast() {
    depths[target] = max(depths[target, default: 0], depth)
    for dependency in targetsById[target]?.dependencies ?? [] {
      dependents[dependency, default: []].insert(target)
      // Check if we have already recorded this target with a greater depth, in which case visiting it again will
      // not increase its depth or any of its children.
      if depths[dependency, default: 0] < depth + 1 {
        worksList.append((dependency, depth + 1))
      }
    }
  }
  return (depths, dependents)
}

private mutating func serializeTopLevelNode(_ value: URIEncodedNode, forKey key: String) throws {
    func unwrapPrimitiveValue(_ node: URIEncodedNode) throws -> URIEncodedNode.Primitive {
        guard case let .primitive(primitive) = node else { throw SerializationError.nestedContainersNotSupported }
        return primitive
    }
    func unwrapPrimitiveOrArrayOfPrimitives(_ node: URIEncodedNode) throws
        -> URIEncodedNode.PrimitiveOrArrayOfPrimitives
    {
        if case let .primitive(primitive) = node { return .primitive(primitive) }
        if case let .array(array) = node {
            let primitives = try array.map(unwrapPrimitiveValue)
            return .arrayOfPrimitives(primitives)
        }
        throw SerializationError.nestedContainersNotSupported
    }
    switch value {
    case .unset:
        // Nothing to serialize.
        break
    case .primitive(let primitive):
        let keyAndValueSeparator: String?
        switch configuration.style {
        case .form: keyAndValueSeparator = "="
        case .simple: keyAndValueSeparator = nil
        case .deepObject: throw SerializationError.deepObjectsWithPrimitiveValuesNotSupported
        }
        try serializePrimitiveKeyValuePair(primitive, forKey: key, separator: keyAndValueSeparator)
    case .array(let array): try serializeArray(array.map(unwrapPrimitiveValue), forKey: key)
    case .dictionary(let dictionary):
        try serializeDictionary(dictionary.mapValues(unwrapPrimitiveOrArrayOfPrimitives), forKey: key)
    }
}

